inputTypesSdl.AttributeInput:
input AttributeInput {
  key: String!
  value: String!
}

inputTypesSdl.CartAddressInput:
input CartAddressInput {
  deliveryAddress: CartDeliveryAddressInput
  copyFromCustomerAddressId: ID
}

inputTypesSdl.CartDeliveryCoordinatesPreferenceInput:
input CartDeliveryCoordinatesPreferenceInput {
  latitude: Float!
  longitude: Float!
  countryCode: CountryCode!
}

inputTypesSdl.CartDeliveryPreferenceInput:
input CartDeliveryPreferenceInput {
  deliveryMethod: [PreferenceDeliveryMethodType!]
  pickupHandle: [String!]
  coordinates: CartDeliveryCoordinatesPreferenceInput
}

inputTypesSdl.CartInputMetafieldInput:
input CartInputMetafieldInput {
  key: String!
  value: String!
  type: String!
}

inputTypesSdl.CartLineParentInput:
input CartLineParentInput {
  lineId: ID
  merchandiseId: ID
}

inputTypesSdl.CartSelectableAddressInput:
input CartSelectableAddressInput {
  address: CartAddressInput!
  selected: Boolean
  oneTimeUse: Boolean
  validationStrategy: DeliveryAddressValidationStrategy
}

returnTypeSdl:
type CartCreatePayload {
  cart: Cart
  userErrors: [CartUserError!]!
  warnings: [CartWarning!]!
}
